import { promises as fs } from 'fs';
import path from 'path';
import { randomUUID } from 'crypto';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

async function ensureFile() {
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.mkdir(DATA_DIR, { recursive: true });
    await fs.writeFile(DATA_FILE, '[]', 'utf8');
  }
}

export async function getBooks() {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, 'utf8');
  try {
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((b) => b.id === id) || null;
}

export async function addBook({ title, author, notes }) {
  const books = await getBooks();
  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: (notes || '').trim(),
    status: 'reading',
    addedAt: new Date().toISOString(),
  };
  books.push(book);
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
  return book;
}

export async function updateBook(id, patch) {
  const books = await getBooks();
  const idx = books.findIndex((b) => b.id === id);
  if (idx === -1) return null;

  const book = books[idx];
  const updated = { ...book, ...patch };

  if (patch.status === 'finished' && book.status !== 'finished') {
    updated.finishedAt = new Date().toISOString();
  }
  if (patch.status === 'reading') {
    delete updated.finishedAt;
  }

  books[idx] = updated;
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
  return updated;
}

export async function deleteBook(id) {
  const books = await getBooks();
  const next = books.filter((b) => b.id !== id);
  await fs.writeFile(DATA_FILE, JSON.stringify(next, null, 2), 'utf8');
  return next.length < books.length;
}

