:root {
  --bg: #f7f6f3;
  --card: #ffffff;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e6e3dc;
  --accent: #4f46e5;
  --accent-ink: #ffffff;
  --green: #15803d;
  --danger: #b91c1c;
  --radius: 12px;
  --shadow: 0 1px 2px rgba(31, 36, 48, 0.06), 0 4px 16px rgba(31, 36, 48, 0.05);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    Helvetica, Arial, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.shell {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 20px 48px;
  min-height: 100vh;
}

.site-header {
  padding: 28px 0 20px;
  border-bottom: 1px solid var(--line);
}

.brand {
  font-size: 1.25rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--ink);
}

.content {
  padding: 28px 0;
}

.site-footer {
  margin-top: 40px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.85rem;
  text-align: center;
}

h1,
h2 {
  margin: 0 0 16px;
}

h2 {
  font-size: 1.15rem;
}

p {
  margin: 0 0 12px;
}

a {
  color: var(--accent);
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
  margin-bottom: 20px;
}

.section {
  margin-bottom: 32px;
}

.section-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
}

.section-title h2 {
  margin: 0;
}

.count {
  color: var(--muted);
  font-size: 0.85rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.book-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 16px;
}

.book-row .meta {
  min-width: 0;
}

.book-row .title {
  font-weight: 600;
  text-decoration: none;
  color: var(--ink);
}

.book-row .title:hover {
  color: var(--accent);
}

.book-row .author {
  color: var(--muted);
  font-size: 0.9rem;
}

.empty {
  color: var(--muted);
  font-style: italic;
  padding: 4px 2px;
}

form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink);
}

input,
textarea {
  font: inherit;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  width: 100%;
}

input:focus,
textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

textarea {
  min-height: 84px;
  resize: vertical;
}

.row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

button,
.btn {
  font: inherit;
  cursor: pointer;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 9px 16px;
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  transition: filter 0.15s ease, background 0.15s ease;
}

button:hover,
.btn:hover {
  filter: brightness(1.05);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button.secondary {
  background: #fff;
  color: var(--ink);
  border-color: var(--line);
}

button.secondary:hover {
  background: #f3f1ec;
}

button.success {
  background: var(--green);
}

button.danger {
  background: #fff;
  color: var(--danger);
  border-color: var(--line);
}

button.danger:hover {
  background: #fef2f2;
  border-color: var(--danger);
}

.error {
  color: var(--danger);
  font-size: 0.9rem;
  margin: 0;
}

.detail-head {
  margin-bottom: 20px;
}

.detail-head .title {
  font-size: 1.6rem;
  font-weight: 700;
  margin: 0 0 4px;
}

.detail-head .author {
  color: var(--muted);
  margin: 0;
}

.status-badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  margin-bottom: 16px;
}

.status-badge.reading {
  background: #eef2ff;
  color: var(--accent);
}

.status-badge.finished {
  background: #ecfdf5;
  color: var(--green);
}

.notes {
  white-space: pre-wrap;
  margin: 0;
}

.share {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 8px 0 20px;
}

.share input {
  flex: 1;
  font-size: 0.85rem;
  color: var(--muted);
}

.back-link {
  display: inline-block;
  margin-bottom: 16px;
  text-decoration: none;
  font-size: 0.9rem;
}

.actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 20px;
}

