export default function BookActions({ bookId, status, redirectOnDelete = false }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);

  async function setStatus(newStatus) {
    if (busy) return;
    setBusy(true);
    await fetch(`/api/books/${bookId}`, {
