        <h2>Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes yet.</p>
        )}

        <BookActions bookId={book.id} status={book.status} redirectOnDelete />
      </div>
    </>
  );
}

export default function NotFound() {
  return (
    <div className="card">
      <h1>Book not found</h1>
      <p>This book may have been deleted, or the link is wrong.</p>
      <p>
        <a href="/">← Back to all books</a>
      </p>
    </div>
  );
}
